+        match config.role_transport_choice("secrets-broker") {
+            Some(fleet_config::RoleTransport::Socket(socket)) => Some(DirectBrokerSource {
+                socket,
+                token_file: fleet_config::Config::home_dir().join(DIRECT_SECRETS_TOKEN_FILE),
